    AFR: ['C'], SVA: ['C'], AIC: ['C'], GFA: ['C'], RJA: ['C'], OMA: ['C'], KQA: ['C'], MEA: ['C'], ALK: ['C'], KAC: ['C'], AFL: ['C'], BBC: ['C'],
