    east:  { name: 'Easterly: land 12L, depart 12R',                short: 'Easterly',  metar: 'OMDB 090400Z 11008KT 9999 FEW030 24/19 Q1015' },
    shamal:{ name: 'Shamal: a strong north-westerly with dust',     short: 'Shamal',    metar: 'OMDB 091200Z 32025G35KT 3000 DU NSC 33/12 Q1010' },
    dust:  { name: 'Dust storm: blowing sand, low visibility',      short: 'Dust',      metar: 'OMDB 091200Z 30030G42KT 0800 BLSA VV010 34/10 Q1006' },
    fog:   { name: 'Dawn fog: CAT III, low visibility operations',  short: 'Fog',       metar: 'OMDB 090200Z 00000KT 0100 R30L/0150N R30R/0200N FG VV001 21/21 Q1016' },
